-- Used-column contracts for the read-only reader, not a projection/writer fixture.
create role authenticated;create role anon;create role service_role;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.role() returns text language sql stable as $$select current_setting('request.jwt.claim.role',true)$$;
grant usage on schema auth to authenticated,anon,service_role;
create function fixture_id(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table tenants(id uuid primary key,status text);
create table profiles(id uuid primary key,tenant_id uuid,role text);
create table view_as_context(actor_user_id uuid,ended_at timestamptz,expires_at timestamptz);
create table platform_authority_grants(profile_id uuid,permission text,effective_from timestamptz,effective_to timestamptz);
create table feature_flags(tenant_id uuid,flag text,value jsonb);
create table tenant_connectors(tenant_id uuid,provider text,connector_id text,enabled boolean,status text);
create table provider_connections(id uuid primary key,tenant_id uuid,provider text,status text,revoked_at timestamptz,verified_at timestamptz);
create table controlplane_change_log(id uuid primary key default gen_random_uuid(),tenant_id uuid,actor text,action text,resource_type text,resource_id text,after jsonb,reason text,view_as_active boolean,source text,correlation_id text);
create table learn_business_input_versions(id uuid primary key,tenant_id uuid,connection_id uuid,provider text,collection text,external_id text,payload jsonb);
create table learn_business_input_pages(id uuid primary key,tenant_id uuid,connection_id uuid,provider text,collection text,committed_at timestamptz);
create table learn_business_input_observations(page_id uuid,version_id uuid);
create table learn_business_input_current_links(id uuid primary key,tenant_id uuid,connection_id uuid,provider text,collection text,external_id text,entity_kind text,entity_table text,entity_id uuid,source_version_id uuid);
create table jobs(id uuid primary key,tenant_id uuid,metadata jsonb);
insert into tenants values(fixture_id(1),'active'),(fixture_id(2),'active');
insert into profiles values(fixture_id(10),fixture_id(1),'owner'),(fixture_id(11),fixture_id(1),'viewer'),(fixture_id(12),fixture_id(2),'owner'),(fixture_id(13),fixture_id(2),'owner');
insert into platform_authority_grants values(fixture_id(13),'platform.controlplane.admin',null,null);
insert into feature_flags values(fixture_id(1),'learn.enabled','true'),(fixture_id(1),'learn.inputs.commusoft.enabled','true');
insert into tenant_connectors values(fixture_id(1),'commusoft','commusoft',true,'active');
insert into provider_connections values(fixture_id(5),fixture_id(1),'commusoft','configured',null,now()),(fixture_id(6),fixture_id(2),'commusoft','configured',null,now());
create function fixture_source(c text,e text,p jsonb,t uuid default fixture_id(1),cn uuid default fixture_id(5),seen timestamptz default clock_timestamp()) returns uuid language plpgsql as $$
declare v uuid:=gen_random_uuid();pg uuid:=gen_random_uuid();begin
 insert into learn_business_input_versions values(v,t,cn,'commusoft',c,e,p);
 insert into learn_business_input_pages values(pg,t,cn,'commusoft',c,seen);
 insert into learn_business_input_observations values(pg,v);return v;
end$$;
select fixture_source('properties','40','{"type":"customer","customerType":13,"companyName":"Source business","contact":{"firstName":"Contact","lastName":"Only"}}');
select fixture_source('properties','41','{"type":"workaddress","parentPropertyID":40}');
select fixture_source('properties','42','{"type":"workaddress","parentPropertyID":99}');
select fixture_source('properties','43','{"type":"workaddress","parentPropertyID":44}');
select fixture_source('properties','44','{"type":"workaddress","parentPropertyID":43}');
