select fixture_source('jobs','101','{"propertyID":41,"description":"008. Commercial Income - Installation","status":"ongoing"}');
select fixture_source('jobs','102','{"propertyID":99,"status":"Open"}');
select fixture_source('jobs','103','{"propertyID":42,"status":"pending"}');
select fixture_source('jobs','104','{"propertyID":43,"status":"on_hold"}');
select fixture_source('jobs','105','{"propertyID":0,"status":"Open"}');
select fixture_source('jobs','106','{"propertyID":40,"status":"Complete"}');
select fixture_source('jobs','107','{"propertyID":40,"status":"Open"}',fixture_id(1),fixture_id(5),'2026-01-01Z');
select fixture_source('jobs','107','{"propertyID":40,"status":"Closed"}',fixture_id(1),fixture_id(5),'2026-01-01Z');
select fixture_source('jobs','100','{"description":"FOREIGN SENTINEL","status":"Open"}',fixture_id(2),fixture_id(6));
select fixture_source('jobs',n::text,jsonb_build_object('propertyID',40,'description','Synthetic extra','status','Open')) from generate_series(200,229)n;
revoke all on all tables in schema public from public,anon,authenticated,service_role;
